function checkScreen(s:GameState){
 const option=s.planChoice??'inspect';const audit=buildCheckEvidence({planChoice:option,condition:s.checkCondition,tasks:s.doTasks,doResult:s.doResult,requestOption:s.doTaskOption});const missing=audit.trueVerdict==='insufficient';const result=s.checkResult;const labels:Record<CheckVerdict,string>={achieved:'Atingida',partial:'Parcialmente atingida','not-achieved':'Não atingida'};const evidenceCard=(item:CheckEvidence)=>`<article class="check-evidence${item.relevant?'':' distraction'}" role="listitem"><span class="check-source">${item.source}</span><strong>${item.taskTitle??item.text}</strong>${item.relevant?`<div class="check-evidence-facts"><div><small>Status registrado</small><b>${item.finalStatus}</b></div><div><small>Destino esperado</small><b>${item.targetStatus}</b></div></div>`:`<div class="check-context-status"><small>Status registrado</small><b>${item.finalStatus??''}</b></div>`}</article>`;const relevantEvidence=audit.evidence.filter(item=>item.relevant).map(evidenceCard).join('');const contextEvidence=audit.evidence.filter(item=>!item.relevant&&item.source.includes('outra frente')).map(evidenceCard).join('');const missingEvidence=missing?audit.evidence.find(item=>item.source==='Auditoria da semana')?.text:'';const verdicts:CheckVerdict[]=['achieved','partial','not-achieved'];const verdictOptions=verdicts.map((verdict,index)=>`<label class="check-verdict"><input type="radio" name="check-verdict" id="check-verdict-${index}" value="${verdict}" ${s.checkVerdictChoice===verdict?'checked':''} ${result?'disabled':''}><span>${labels[verdict]}</span></label>`).join('');const feedback=result?`<section class="check-feedback" aria-live="polite"><strong>Resultado: ${labels[result.trueVerdict as CheckVerdict]??'Sem evidência suficiente'}</strong><p>${result.explanation}</p><button id="advance" data-action="continue-check" type="button">Semana 4 · ACT</button></section>`:'';
 const content=`<style>.check-page{max-width:1240px;margin:0 auto;padding:20px 28px 28px;color:#253132}.check-header{margin:0 0 18px;padding-bottom:12px;border-bottom:1px solid #d7e0e1}.check-eyebrow{color:#087c86;font-size:12px;font-weight:800;letter-spacing:.08em}.check-investigation,.check-judgment,.check-feedback{margin:18px 0;padding:22px 24px;border:1px solid #d5e0e1;border-radius:16px;background:#fff}.check-section-head{display:flex;align-items:baseline;justify-content:space-between;gap:16px;margin-bottom:16px}.check-section-head h1,.check-section-head h2,.check-judgment h2,.check-feedback h2{margin:0;font-size:21px;line-height:1.25}.check-section-head p{margin:0;color:#586568;font-size:13px}.check-insufficient{display:grid;gap:5px;margin:0 0 14px;padding:12px 14px;border-left:4px solid #c29236;border-radius:8px;background:#fff8e8;color:#50482f;font-size:14px}.check-insufficient p{margin:0;font-size:13px;line-height:1.5}.check-evidence-group h2{margin:0 0 10px;font-size:14px;color:#425254}.check-evidence-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.check-evidence{display:grid;align-content:start;gap:12px;min-width:0;padding:16px;border:1px solid #cbdadb;border-radius:12px;background:#f8fbfb}.check-evidence>strong{font-size:15px;line-height:1.4;font-weight:700}.check-source{width:max-content;max-width:100%;color:#58696b;font-size:11px;font-weight:650}.check-evidence-facts{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding-top:12px;border-top:1px solid #dce6e6}.check-evidence-facts>div,.check-context-status{display:grid;gap:5px;min-width:0}.check-evidence-facts small,.check-context-status small{color:#647476;font-size:11px}.check-evidence-facts b,.check-context-status b{font-size:14px;line-height:1.35}.check-context{display:grid;grid-template-columns:minmax(180px,.55fr) minmax(0,1.45fr);gap:14px;align-items:start;margin-top:20px;padding:15px 17px;border-radius:12px;background:#f4f2eb}.check-context-copy h2{margin:0 0 5px;font-size:14px}.check-context-copy p{margin:0;color:#59605a;font-size:12px;line-height:1.5}.check-context .check-evidence-list{grid-template-columns:repeat(2,minmax(0,1fr))}.check-evidence.distraction{background:#fff;border-color:#e0ddd2}.check-context-status{display:flex;align-items:baseline;gap:8px;padding-top:10px;border-top:1px solid #e3e0d7}.check-hint{margin:16px 0 0;padding:12px 14px;border-left:3px solid #c29236;border-radius:8px;background:#fff7e7;color:#5a4828;font-size:13px;line-height:1.5}.check-judgment{margin-top:22px;padding:24px}.check-judgment h2{margin-bottom:16px}.check-verdicts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.check-verdict{display:flex;align-items:center;gap:12px;min-height:58px;padding:12px 16px;border:1px solid #ccd9da;border-radius:11px;background:#f8fbfb;font-size:15px;font-weight:700;cursor:pointer}.check-verdict input{width:20px;height:20px;flex:none;accent-color:#087c86}.check-verdict:has(input:checked){border-color:#087c86;background:#eaf7f6;box-shadow:inset 0 0 0 1px #087c86}.check-submit,.check-feedback button{min-height:46px;margin-top:16px;padding:0 24px;border:0;border-radius:10px;background:#087c86;color:white;font-weight:800;cursor:pointer}.check-submit:disabled{background:#aebabc;cursor:not-allowed}.check-feedback{border-color:#9bcfc4;background:#f1faf6}.check-feedback>strong{font-size:17px}.check-feedback>p{margin:10px 0;color:#4c5b5c;font-size:14px;line-height:1.55}.check-page :where(button,input):focus-visible{outline:3px solid #025a8a;outline-offset:3px}@media(max-width:800px){.check-page{padding:14px}.check-investigation,.check-judgment,.check-feedback{padding:16px}.check-section-head{align-items:flex-start;flex-direction:column;gap:6px}.check-evidence-list{grid-template-columns:1fr}.check-context{grid-template-columns:1fr}.check-context .check-evidence-list{grid-template-columns:1fr}.check-verdicts{grid-template-columns:1fr}.check-submit,.check-feedback button{width:100%}}@media(prefers-reduced-motion:reduce){.check-page *{scroll-behavior:auto!important;transition:none!important}}</style><main class="check-page"><header class="check-header"><span class="check-eyebrow">CHECK · SEMANA ${s.week} DE 4</span></header><section class="check-investigation" aria-label="Evidências do CATO">${missing?`<div class="check-insufficient" role="status"><strong>Sem registros suficientes para avaliar a meta.</strong><p>${missingEvidence}</p></div>`:''}<div class="check-section-head"><h1>Compare a execução com a meta</h1><p>Use o status final e o destino esperado de cada tarefa.</p></div>${relevantEvidence?`<section class="check-evidence-group" aria-labelledby="check-target-title"><h2 id="check-target-title">Tarefas da meta</h2><div class="check-evidence-list" role="list">${relevantEvidence}</div></section>`:''}${contextEvidence?`<section class="check-context" aria-labelledby="check-context-title"><div class="check-context-copy"><h2 id="check-context-title">Contexto de outra frente</h2><p>Este registro não define o resultado da meta.</p></div><div class="check-evidence-list" role="list">${contextEvidence}</div></section>`:''}${audit.hint?`<p class="check-hint">${audit.hint}</p>`:''}</section><section class="check-judgment" aria-labelledby="verdict-title"><h2 id="verdict-title">Qual foi o resultado da meta?</h2><fieldset ${result?'disabled':''}><legend class="sr-only">Escolha um veredito</legend><div class="check-verdicts">${verdictOptions}</div></fieldset>${!result?`<button class="check-submit" data-action="complete-check" type="button" ${s.checkVerdictChoice?'':'disabled'}>Confirmar</button>`:''}</section>${feedback}</main>`;return gameFrame(s,'CHECK',content)
}
function act(s:GameState){
 const round=s.actRound;
 if(!round)return gameFrame(s,'ACT',`<main class="cato-act"><h1>Conselho do CATO</h1><p>Não há rodada registrada. Retorne pelo CHECK.</p></main>`);
 const result=s.actResult;
 const selected=new Set(s.actSelectedIds);
 const signed=(value:number)=>value>0?`+${value}`:String(value);
 const sourceNames={PLAN:'Direcionamento',DO:'Execução',CHECK:'Verificação'};const claims=round.claims.map((claim,index)=>`<label class="act-claim act-source-${claim.source.toLowerCase()}${result?(claim.truth?' is-true':' is-false'):selected.has(claim.id)?' is-selected':''}"><span class="act-claim-source"><span class="act-claim-source-code">${claim.source}</span><span class="act-claim-source-name">${sourceNames[claim.source]}</span>${result?`<span class="act-claim-truth">${claim.truth?'Verdadeira':'Falsa'}</span>`:''}</span><span class="act-claim-body"><span class="act-claim-text">${claim.statement}</span>${result?`<span class="act-claim-evidence"><strong>Registro</strong>${claim.explanation}</span>`:''}</span><input type="checkbox" id="act-claim-${index}" data-act-claim="${claim.id}" ${selected.has(claim.id)?'checked':''} ${result?'disabled':''}></label>`).join('');
 const brief=`${round.hint?`<p class="act-hint">${round.hint}</p>`:''}`;
 const feedback=result?`<section class="act-feedback" aria-live="polite"><div class="act-feedback-head"><div><span class="act-kicker">${result.correct?'DEVOLUTIVA DO CONSELHO · CORRETO':'DEVOLUTIVA DO CONSELHO · REVISE'}</span><h2>${result.correct?'Você interpretou o ciclo corretamente.':'Compare as afirmações com os registros.'}</h2></div><div class="act-effects"><span>Atrasos ${signed(result.effects.delay)} p.p.</span><span>Qualidade ${signed(result.effects.quality)}</span><span>Moral ${signed(result.effects.moral)}</span><span>Saldo ${signed(result.effects.balance)} MoedACTAs</span></div></div><article class="act-lesson"><strong>APRENDIZADO · operação</strong><p>${result.lesson.text}</p><span>Próxima operação: ${result.lesson.nextAction}</span></article><button class="act-primary" data-action="act-continue" type="button">Encerrar operação</button></section>`:'';
 const content=`<style>.cato-act{max-width:1240px;margin:auto;padding:20px 28px 28px;color:#253132}.act-header{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:20px;padding-bottom:14px;border-bottom:1px solid #d7e0e1}.act-kicker{color:#087c86;font-size:12px;font-weight:800;letter-spacing:.08em}.act-header h1{margin:4px 0 0;font-size:28px;line-height:1.2}.act-week{flex:none;padding:9px 13px;border-radius:999px;background:#e6f4f3;color:#17666b;font-size:12px;font-weight:800}.act-board,.act-feedback{margin:16px 0;padding:22px 24px;border:1px solid #d5e0e1;border-radius:16px;background:#fff}.act-board h2{margin:0 0 6px;font-size:21px}.act-board>p{margin:0 0 16px;color:#586568;font-size:14px}.act-claims{display:grid;grid-template-columns:1fr;gap:12px}.act-claim{display:grid;grid-template-columns:170px minmax(0,1fr) 28px;align-items:center;gap:20px;min-width:0;padding:18px 20px;border:1px solid #d6e0e1;border-left:5px solid #087c86;border-radius:12px;background:#fbfcfc;cursor:pointer}.act-source-plan{border-left-color:#087c86}.act-source-do{border-left-color:#c29236}.act-source-check{border-left-color:#577c9a}.act-claim:has(input:checked){background:#eaf7f6;box-shadow:inset 0 0 0 1px #087c86}.act-claim.is-true{border-color:#73ae91;border-left-color:#39815c;background:#f1faf4}.act-claim.is-false{border-color:#d59a91;border-left-color:#b45b4e;background:#fff5f3}.act-claim-source{display:grid;gap:4px;align-content:center;min-height:58px;padding-right:16px;border-right:1px solid #dce5e5}.act-claim-source-code{font-size:16px;font-weight:850;letter-spacing:.04em;color:#087c86}.act-source-do .act-claim-source-code{color:#946717}.act-source-check .act-claim-source-code{color:#466b89}.act-claim-source-name{font-size:12px;color:#586568}.act-claim-truth{width:max-content;margin-top:3px;padding:4px 8px;border-radius:999px;background:#e1efe5;color:#286a49;font-size:11px;font-weight:800}.is-false .act-claim-truth{background:#f3e3e0;color:#94483e}.act-claim-body{display:grid;gap:12px;min-width:0}.act-claim-text{font-size:16px;line-height:1.5;font-weight:650}.act-claim-evidence{display:grid;gap:4px;padding-top:10px;border-top:1px solid #dce7e4;color:#4f5c5d;font-size:13px;line-height:1.5}.act-claim-evidence strong{font-size:11px;text-transform:uppercase;letter-spacing:.04em;color:#536366}.act-claim input{width:24px;height:24px;margin:0;accent-color:#087c86;cursor:pointer}.act-primary{min-height:48px;margin-top:16px;padding:0 24px;border:0;border-radius:10px;background:#087c86;color:#fff;font-weight:800;font-size:15px;cursor:pointer}.act-primary:disabled{background:#adb8b9;cursor:not-allowed}.cato-act :where(button,input):focus-visible{outline:3px solid #025a8a;outline-offset:3px}.act-feedback{border-color:#9bcfc4;background:#f2faf6}.act-feedback-head{display:flex;justify-content:space-between;align-items:center;gap:18px}.act-feedback h2{margin:4px 0;font-size:20px}.act-effects{display:flex;flex-wrap:wrap;gap:7px}.act-effects span{padding:7px 9px;border-radius:8px;background:#fff;font-size:12px;font-weight:750}.act-lesson{margin-top:14px;padding:14px 16px;border-left:4px solid #c29236;border-radius:9px;background:#fff8e9;font-size:14px;line-height:1.5}.act-lesson p{margin:5px 0}.act-lesson>strong{font-size:11px;color:#72581f;letter-spacing:.04em}.act-lesson span{color:#566;font-size:13px}.act-page-empty{max-width:760px;margin:24px auto;padding:20px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:760px){.cato-act{padding:14px}.act-header{align-items:flex-start}.act-header h1{font-size:23px}.act-board,.act-feedback{padding:16px}.act-claim{grid-template-columns:minmax(0,1fr) 28px;gap:12px;padding:14px}.act-claim-source{grid-column:1;grid-row:1;grid-template-columns:auto 1fr;align-items:center;min-height:0;padding:0 0 9px;border-right:0;border-bottom:1px solid #dce5e5}.act-claim-source-code{font-size:14px}.act-claim-source-name{font-size:12px}.act-claim-truth{grid-column:2;grid-row:1;margin:0}.act-claim-body{grid-column:1/-1;grid-row:2}.act-claim input{grid-column:2;grid-row:2;align-self:start}.act-claim-text{font-size:14px}.act-claim-evidence{grid-column:1/-1}.act-feedback-head{align-items:flex-start;flex-direction:column}.act-primary{width:100%}}@media(prefers-reduced-motion:reduce){.cato-act *{scroll-behavior:auto!important;transition:none!important;animation:none!important}}</style><main class="cato-act"><header class="act-header"><div><span class="act-kicker">ACT · CONSELHO DO CATO</span><h1>Aprenda com o ciclo</h1></div><span class="act-week">Semana ${s.week} de 4</span></header>${brief}<section class="act-board" aria-labelledby="claims-title"><h2 id="claims-title">Quais afirmações são verdadeiras?</h2>${!result?`<p>Marque as afirmações corretas.</p><div class="act-claims" role="group" aria-label="Afirmações do ciclo">${claims}</div><button class="act-primary" data-action="act-submit" type="button" ${s.actSelectedIds.length?'':'disabled'}>Confirmar resposta</button>`:`<div class="act-claims" role="list" aria-label="Veracidade das afirmações">${claims}</div>`}</section>${feedback}</main>`;
 return gameFrame(s,'ACT',content)
}
function endScreen(s:GameState,source:string){const win=s.phase==='victory';let h=body(source);h=h.replace(/<span class="mock(?:-label)?">[\s\S]*?<\/span>/,'').replace(/<span class="mock-label">[\s\S]*?<\/span>/,'');h=h.replace(/<span class="eyebrow">Resultado: [^<]+<\/span>/,`<span class="eyebrow">Resultado: ${win?'vitória':'derrota'}</span>`);h=replaceId(h,'title',win?'Operação<br>resgatada!':'Não foi dessa Vez!');h=replaceId(h,'title',win?'Operação<br>resgatada!':'Não foi dessa Vez!');h=h.replace(/<p class="lead">[\s\S]*?<\/p>/,`<p class="lead">${win?'Você cumpriu as metas da semana 4.':'Confira quais metas ficaram fora do objetivo.'}</p>`);h=h.replace(/<(?:div|p) class="stars"[\s\S]*?<\/(?:div|p)>/,'');h=h.replace(/<details class="summary"[\s\S]*?<\/details>/,'');h=h.replace(/<button class="button secondary"[^>]*>[^<]*<\/button>/,'');const criteria=`<section class="criteria" aria-label="Critérios operacionais"><article class="criterion${s.delay<=40?' met':''}"><div><div class="name">Atrasos</div><div class="target">Alvo: ≤40%</div></div><div class="state">${s.delay<=40?(win?'Aprovado':'Atingido'):'Não atingido'}</div></article><article class="criterion${s.quality>=75?' met':''}"><div><div class="name">Qualidade</div><div class="target">Alvo: ≥75%</div></div><div class="state">${s.quality>=75?(win?'Aprovado':'Atingido'):'Não atingido'}</div></article><article class="criterion${s.balance>=0?' met':''}"><div><div class="name">Orçamento</div><div class="target">Meta: não negativo</div></div><div class="state">${s.balance>=0?(win?'Aprovado':'Atingido'):'Não atingido'}</div></article></section>`;h=h.replace(/<section class="criteria"[\s\S]*?<\/section>/,criteria);h=h.replace(/<aside class="context">[\s\S]*?<\/aside>/,'');h=h.replace(/<div class="scene" aria-hidden="true">[\s\S]*?<\/div>/,'<div class="scene" aria-hidden="true"><img class="coin-hero" src="/moedacta.svg" alt=""></div>');h=h.replace(/<div class="guide">[\s\S]*?<\/div>/,`<div class="guide"><span>${win?'\u201c\u00d3timo trabalho. Leve esse aprendizado para a pr\u00f3xima etapa.\u201d':'\u201cH\u00e1 aprendizados importantes aqui. Vamos rever os resultados.\u201d'}</span></div>`);h=h.replace(/<button class="button primary"[^>]*>[^<]*<\/button>/,`<button class="button primary" type="button" data-action="home">Voltar para a Home</button>`);h=h.replace('Composição visual · dados ilustrativos','');h=h.replace(/<p class="note"[^>]*>[\s\S]*?<\/p>/,'');h=h.replace(/<div class="veil" id="veil"[\s\S]*?<div class="status"/i,`<div class="status"`);return h}
function indicatorCards(s:GameState){const cards:[string,string,string][]=[['Atrasos',`${s.delay}%`,'▤'],['Qualidade',`${s.quality}%`,'✓'],['Moral',`${s.moral}%`,'☺']];return `<style>.current-indicators{width:min(1320px,calc(100% - 40px));margin:12px auto;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;font-family:'Plus Jakarta Sans',sans-serif}.current-indicator{min-width:0;min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border:1px solid #d6dcdd;border-radius:18px;background:#fff}.current-indicator dt{margin:0 0 4px;color:#586568;font-size:13px}.current-indicator dd{margin:0;color:#253132;font-size:27px;line-height:1.1;font-weight:750;font-variant-numeric:tabular-nums}.current-indicator-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;background:#e3f7f7;color:#087c86;font-size:19px}.current-indicator.balance{border-color:#b5dddf;background:#e3f7f7}.current-indicator.balance dd{color:#087c86;font-size:20px}.current-indicator.balance img{width:56px;height:64px;object-fit:contain}@media(max-width:760px){.current-indicators{width:calc(100% - 24px);grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.current-indicator{min-height:66px;padding:9px 11px}.current-indicator dd{font-size:23px}.current-indicator.balance dd{font-size:16px}.current-indicator.balance img{width:44px;height:52px}}</style><dl class="current-indicators" aria-label="Indicadores atuais">${cards.map(([label,value,icon])=>`<div class="current-indicator"><div><dt>${label}</dt><dd>${value}</dd></div><span class="current-indicator-icon" aria-hidden="true">${icon}</span></div>`).join('')}<div class="current-indicator balance"><div><dt>Saldo</dt><dd>${s.balance} MoedACTAs</dd></div><img src="/moedacta.svg" alt=""></div></dl>`}
function addCurrentIndicators(s:GameState,html:string){if(s.phase==='plan')html=html.replace(/<(?:section|dl) class="metrics"[\s\S]*?<\/(?:section|dl)>/,'');if(s.phase==='victory'||s.phase==='defeat'){html=html.replace(/<aside class="context">[\s\S]*?<\/aside>/,'')}const cards=indicatorCards(s);if(s.phase==='home'){html=html.replace(/<\/header>/i,`</header>${cards}`);html=html.replace('</head>', '<style>.page:has(.current-indicators) main{height:calc(100vh - 192px);padding-top:10px;padding-bottom:10px}@media(max-width:900px){.page:has(.current-indicators) main{height:calc(100vh - 168px);padding:8px 20px}}</style></head>');return html}if(/<\/header>/i.test(html))return html.replace(/<\/header>/i,`</header>${cards}`);if(/<div class="page"[^>]*>/i.test(html))return html.replace(/<div class="page"[^>]*>/i,match=>`${match}${cards}`);if(/<main[^>]*>/i.test(html))return html.replace(/<main[^>]*>/i,match=>`${match}${cards}`);return `${cards}${html}`}
export function renderReferenceScreen(s:GameState){let html:string;switch(s.phase){case'home':html=home();break;case'plan':html=plan(s);break;case'do':html=gameFrame(s,'DO',doScreen(s));break;case'check':html=checkScreen(s);break;case'act':html=act(s);break;case'victory':html=endScreen(s,victoryHtml);break;case'defeat':html=endScreen(s,defeatHtml);break}return addCurrentIndicators(s,html)}













